style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
html, body {
    background: url("https://i.imgur.com/K7AVqoa.jpeg") no-repeat center center fixed !important;
    background-size: cover !important;
    background-attachment: fixed !important;
  }

  /* Forzar que los contenedores sean transparentes */
  #app-container, #container-main, #navigation-container, #content {
    background: transparent !important;
  }

  /* También quitar fondo blanco de paneles */
  .container, .section, .content, .rbx-header, .rbx-navbar, .rbx-footer {
    background: transparent !important;
  }
}
